const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const rosetteIcon='<circle cx="20" cy="20" r="6"/><g>'+Array.from({length:6},(_,i)=>`<ellipse cx="20" cy="8" rx="4" ry="7" transform="rotate(${i*60} 20 20)"/>`).join('')+'</g>';
const motifs={rosette:{label:'Rosette',icon:rosetteIcon},scroll:{label:'Scroll',icon:'<path d="M7 28c18 2 4-22 19-20 11 1 1 17 7 14"/><path d="M10 10c2 8 10 6 12 0"/>'},botanical:{label:'Leaf vine',icon:'<path d="M20 34C7 26 7 11 29 7"/><path d="M18 27C8 27 6 18 8 15c6 0 10 3 10 12M23 18c0-8 6-11 12-10 0 6-4 9-12 10"/>'},diamond:{label:'Openwork',icon:'<path d="M20 3 36 20 20 37 4 20Z M20 10 29 20 20 30 11 20Z"/><path d="M4 20h32M20 3v34"/>'}};
let settings={motif:'rosette',repeat:'halfdrop',ground:'diamond',density:55,weight:3,detail:'balanced',edge:'repeat',surface:'ink',quality:'medium'};let currentImage='ai-lace-study.png',history=[];let sourceImage=null;
function motifSvg(){const m=motifs[settings.motif];return `<svg viewBox="0 0 40 40" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><g>${m.icon}</g></svg>`}
function setupChoices(){
 $('#motifChoices').innerHTML=Object.entries(motifs).map(([k,m])=>`<button type="button" data-motif="${k}" aria-pressed="${k===settings.motif}">${motifSvg()}<span>${m.label}</span></button>`).join('');
 $$('#motifChoices button').forEach(b=>b.onclick=()=>{settings.motif=b.dataset.motif;sync();});
 $$('#surfaceChoices button').forEach(b=>b.onclick=()=>{settings.surface=b.dataset.surface;$$('#surfaceChoices button').forEach(x=>x.setAttribute('aria-pressed',x===b));syncRecipe();});
}
function sync(){for(const [k,v] of Object.entries(settings)){const el=document.querySelector(`[name="${k}"]`);if(el)el.value=v}$('#densityValue').textContent=settings.density+'%';$('#weightValue').textContent=settings.weight+' / 5';$$('#motifChoices button').forEach(b=>b.setAttribute('aria-pressed',b.dataset.motif===settings.motif));syncRecipe();drawSketch();}
function recipe(){const m=motifs[settings.motif].label.toLowerCase();const surface={ink:'black material with white open voids',thread:'warm ivory thread on a cool white ground',cutwork:'paper-cut surface with clean shadowless edges'}[settings.surface];return `Create one square, flat lace pattern study for material research.\nMotif: ${m}.\nArrangement: ${settings.repeat.replace('halfdrop','half-drop rows').replace('grid','square translation grid').replace('mirror','bilateral mirror repeat').replace('radial','radial medallion').replace('organic','flowing organic field')}.\nGround: ${settings.ground.replace('diamond','diamond mesh').replace('hexagonal','hexagonal net').replace('bridges','open connecting bridges').replace('none','no ground; separated motifs')}.\nOpen space: ${settings.density} percent. Thread weight: ${settings.weight} of 5. Detail: ${settings.detail}. Edge: ${settings.edge}. Surface: ${surface}.\nOrthographic, edge-to-edge, no perspective, shadows, garments, boats, lettering or watermark. Keep the pattern visually connected and show two scales: a legible motif and a smaller ground. This is an exploratory specimen, not a certified seamless repeat or engineering drawing.`}
function syncRecipe(){$('#promptPreview').textContent=recipe()}
function drawSketch(){const ground=settings.ground==='diamond'?'M0 0L40 40M40 0L0 40':'M20 0V40M0 20H40';$('#sketch').innerHTML=`<svg viewBox="0 0 240 240" xmlns="http://www.w3.org/2000/svg"><defs><pattern id="g" width="40" height="40" patternUnits="userSpaceOnUse"><g stroke="#617c89" stroke-width=".7" opacity=".4"><path d="${ground}"/></g></pattern></defs><rect width="240" height="240" fill="#f3f7f8"/><rect width="240" height="240" fill="url(#g)"/><g transform="translate(120 120) scale(1.5)" fill="none" stroke="#253943" stroke-width="1.4">${motifs[settings.motif].icon}</g></svg>`}
function showPage(id){$$('.page').forEach(p=>{p.hidden=p.id!==id;p.classList.toggle('active',p.id===id)});$$('[data-page]').forEach(b=>b.setAttribute('aria-current',b.dataset.page===id?'page':'false'));location.hash=id}
$$('[data-page]').forEach(b=>b.onclick=()=>showPage(b.dataset.page));
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('visible');setTimeout(()=>$('#toast').classList.remove('visible'),2800)}
function setLoading(on){$('#generationOverlay').hidden=!on;$('#generate').disabled=on}
async function checkConnection(){try{const r=await fetch('/api/health');const d=await r.json();$('#apiStatus').textContent=d.configured?'OpenAI image connection ready':'API key needed on server';$('#apiStatus').classList.toggle('ready',!!d.configured);return d.configured}catch{$('#apiStatus').textContent='Local server only · API unavailable';$('#apiStatus').classList.remove('ready');return false}}
async function generate(e){e.preventDefault();$('#generationError').hidden=true;setLoading(true);const started=Date.now();try{const r=await fetch('/api/generate',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({settings})});const d=await r.json();if(!r.ok)throw new Error(d.error||'Generation failed');currentImage=`data:image/png;base64,${d.image}`;$('#resultImage').src=currentImage;$('#resultImage').alt='Generated lace pattern study';$('#specimenLabel').textContent='GENERATED / '+new Date().toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'});$('#imageCaption').textContent=`OpenAI image study · ${d.model} · ${((Date.now()-started)/1000).toFixed(1)}s`;$('#resultNote').textContent='This is a visual hypothesis. Pin it, download it, or test it in Image study.';toast('New pattern generated');checkConnection()}catch(err){$('#generationError').hidden=false;$('#generationError').textContent=err.message.includes('API key')?'Add OPENAI_API_KEY to the server environment, then restart.':err.message;toast('Generation could not complete')}finally{setLoading(false)}}
$('#patternForm').onsubmit=generate;
$$('#patternForm select,#patternForm input[type=range]').forEach(el=>el.oninput=()=>{settings[el.name]=el.type==='range'?Number(el.value):el.value;sync()});
$('#reset').onclick=()=>{settings={motif:'rosette',repeat:'halfdrop',ground:'diamond',density:55,weight:3,detail:'balanced',edge:'repeat',surface:'ink',quality:'medium'};sync()};
$('#outputView').onclick=()=>{$('#resultImage').hidden=false;$('#sketch').hidden=true;$('#outputView').setAttribute('aria-pressed','true');$('#sketchView').setAttribute('aria-pressed','false')};$('#sketchView').onclick=()=>{$('#resultImage').hidden=true;$('#sketch').hidden=false;$('#outputView').setAttribute('aria-pressed','false');$('#sketchView').setAttribute('aria-pressed','true');drawSketch()};
$('#downloadImage').onclick=()=>{const a=document.createElement('a');a.href=currentImage;a.download='lace-lab-pattern.png';a.click()};$('#fullImage').onclick=()=>{$('#enlargedImage').src=currentImage;$('#imageDialog').showModal()};
$('#pin').onclick=()=>{history.push({src:currentImage,settings:{...settings}});$('#history').hidden=false;$('#historyItems').innerHTML=history.map((h,i)=>`<button class="history-item" data-i="${i}"><img src="${h.src}" alt="Pinned study ${i+1}"><span>${motifs[h.settings.motif].label}<br>${h.settings.repeat}</span></button>`).join('');$$('.history-item').forEach(b=>b.onclick=()=>{$('#resultImage').src=history[b.dataset.i].src;currentImage=history[b.dataset.i].src});toast('Study pinned')};
$('#copyPrompt').onclick=async()=>{await navigator.clipboard?.writeText(recipe());toast('Recipe copied')};$('#exportRecipe').onclick=()=>{const blob=new Blob([JSON.stringify({version:2,createdAt:new Date().toISOString(),settings,recipe:recipe(),pinned:history.map(x=>x.settings)},null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='lace-lab-study.json';a.click()};$('#checkConnection').onclick=checkConnection;
$('#studyResult').onclick=()=>showPage('analysis');
const cases=[
 {id:'01',title:'Lace Square',meta:'Italy · 1500s–1600s · reticella needle lace',image:'https://openaccess-cdn.clevelandart.org/1920.1098/1920.1098_web.jpg',url:'https://www.clevelandart.org/art/1920.1098',tags:['geometric','star + ring','square repeat'],obs:'A central eight-pointed star sits inside a circular ring; a knotted grid connects it to a square border.',q:'When cells join, does the corner become a new motif?',family:'diamond'},
 {id:'02',title:'Pointed edging',meta:'Genoa · 17th century · bobbin lace',image:'https://openaccess-cdn.clevelandart.org/1920.985/1920.985_web.jpg',url:'https://www.clevelandart.org/art/1920.985',tags:['ground','wheel repeat','pointed edge'],obs:'Wheels and pointed pendants create two rhythms. The edge is not simply a crop of the interior.',q:'How can a one-direction repeat keep its border continuous?',family:'diamond'},
 {id:'03',title:'Floral mesh',meta:'Flanders · 17th–18th century · bobbin lace',image:'https://openaccess-cdn.clevelandart.org/1923.1040/1923.1040_web.jpg',url:'https://www.clevelandart.org/art/1923.1040',tags:['botanical','mesh','bilateral'],obs:'Scrolling foliage sits against fine mesh. Compare bilateral balance with local variation.',q:'Does the ground connect the flowers, or do the branches become the ground?',family:'botanical'},
 {id:'04',title:'Mixed construction',meta:'Italy · 17th century · needle and bobbin lace',image:'https://openaccess-cdn.clevelandart.org/1920.1237/1920.1237_web.jpg',url:'https://www.clevelandart.org/art/1920.1237',tags:['geometric','S-connectors','islands'],obs:'Circles, flowers and curved connectors form one field. Separate solid motifs from bridges.',q:'How many islands remain if the connectors are removed?',family:'rosette'},
 {id:'05',title:'Floral needle lace',meta:'Alençon, France · 1840–1860 · needle lace',image:'https://openaccess-cdn.clevelandart.org/1930.652/1930.652_web.jpg',url:'https://www.clevelandart.org/art/1930.652',tags:['botanical','swag','scalloped edge'],obs:'Swags, branches, mesh and edge work at different scales. Keep those scales distinct.',q:'What must simplify when thread-scale lace becomes a cut panel?',family:'botanical'},
 {id:'06',title:'Maltese collar',meta:'Malta · third quarter 19th century · silk',image:'https://collectionapi.metmuseum.org/api/collection/v1/iiif/158824/332483/main-image',url:'https://www.metmuseum.org/art/collection/search/158824',tags:['ground','Maltese cross','leaf + tulip'],obs:'A leaf and tulip vocabulary is held by a Maltese-cross ground. The ground is part of the identity, not empty filler.',q:'Can the cross ground be varied while keeping the local grammar?',family:'botanical'},
 {id:'07',title:'Amoy Lace Guild sample',meta:'Xiamen, China · 1905–1912 · linen Torchon insertion',image:'https://ids.si.edu/ids/deliveryService?id=NMAH-AHB2013q001588',url:'https://www.si.edu/object/amoy-lace-guild-bobbin-lace-sample:nmah_624030',tags:['geometric','roseground','half-stitch trail'],obs:'Diamond motifs, roseground and half-stitch trails show how a small band can carry several densities.',q:'Which density changes first when the band becomes a surface?',family:'diamond'}
];
function renderAtlas(filter='all'){const data=cases.filter(c=>filter==='all'||c.tags.includes(filter));$('#caseCount').textContent=String(data.length).padStart(2,'0')+' specimens';$('#references').innerHTML=data.map(c=>`<article class="reference-card" data-tags="${c.tags.join(' ')}"><div class="image-wrap" data-id="${c.id}"><img src="${c.image}" alt="${c.title}, ${c.meta}" loading="lazy" onerror="this.outerHTML='<p class=\'image-error\'>Image unavailable<br>Open the collection record below ↗</p>'"><span class="image-index">CASE / ${c.id}</span></div><div class="body"><p class="eyebrow">${c.meta}</p><h2>${c.title}</h2><div class="pattern-tags">${c.tags.map(t=>`<span>${t}</span>`).join('')}</div><p>${c.obs}</p><div class="case-actions"><button data-use="${c.id}">Use this grammar ↗</button><button data-open="${c.id}">Read case ↗</button></div></div></article>`).join('');$$('[data-open]').forEach(b=>b.onclick=()=>openCase(b.dataset.open));$$('[data-use]').forEach(b=>b.onclick=()=>{const c=cases.find(x=>x.id===b.dataset.use);settings.motif=c.family;sync();showPage('studio');toast('Grammar loaded as a starting point')});$$('.image-wrap').forEach(x=>x.onclick=()=>openCase(x.dataset.id))}
function openCase(id){const c=cases.find(x=>x.id===id);$('#caseDetail').innerHTML=`<div class="detail-image"><img src="${c.image}" alt="${c.title}"></div><div><p class="eyebrow">CASE / ${c.id} · LACE PATTERN STUDY</p><h2>${c.title}</h2><p>${c.meta}</p><div class="pattern-tags">${c.tags.map(t=>`<span>${t}</span>`).join('')}</div><p><b>Observed structure</b><br>${c.obs}</p><p><b>Research question</b><br>${c.q}</p><a class="source-link" href="${c.url}" target="_blank" rel="noopener">Open collection record ↗</a><p class="micro-copy">Use the source page for rights and object context. This reading is a working abstraction for Lace Lab.</p></div>`;$('#caseDialog').showModal()}
$$('#atlasFilters button').forEach(b=>b.onclick=()=>{$$('#atlasFilters button').forEach(x=>x.setAttribute('aria-pressed',x===b));renderAtlas(b.dataset.filter)});
function binaryStats(mask,w,h){let black=0,components=0,seen=new Uint8Array(mask.length),q=new Int32Array(mask.length);for(let i=0;i<mask.length;i++){black+=mask[i];if(!mask[i]||seen[i])continue;let a=0,z=1;q[0]=i;seen[i]=1;while(a<z){const p=q[a++],x=p%w,y=p/w;for(let dy=-1;dy<=1;dy++)for(let dx=-1;dx<=1;dx++){const nx=x+dx,ny=y+dy,n=ny*w+nx;if(nx>=0&&nx<w&&ny>=0&&ny<h&&mask[n]&&!seen[n]){seen[n]=1;q[z++]=n}}}if(z>3)components++}return{open:100*(1-black/mask.length),components}}
function analyze(){if(!sourceImage)return;const t=Number($('#threshold').value);$('#thresholdValue').textContent=t;const c=$('#analysisCanvas'),scale=Math.min(1,640/sourceImage.width,640/sourceImage.height),w=Math.round(sourceImage.width*scale),h=Math.round(sourceImage.height*scale);c.width=w;c.height=h;const ctx=c.getContext('2d',{willReadFrequently:true});ctx.drawImage(sourceImage,0,0,w,h);const d=ctx.getImageData(0,0,w,h),mask=new Uint8Array(w*h),inv=$('#imageInvert').checked;for(let i=0;i<mask.length;i++){const p=i*4,lum=.2126*d.data[p]+.7152*d.data[p+1]+.0722*d.data[p+2];mask[i]=(inv?lum>=t:lum<t)?1:0;const col=mask[i]?31:250;d.data[p]=d.data[p+1]=d.data[p+2]=col;d.data[p+3]=255}ctx.putImageData(d,0,0);const s=binaryStats(mask,w,h);let both=0,union=0;for(let y=0;y<h;y++)for(let x=0;x<w;x++){const a=mask[y*w+x],b=mask[y*w+w-1-x];both+=a&&b;union+=a||b}$('#imageStatus').textContent=`${w} × ${h} analysis pixels · local processing`;$('#imageMetrics').innerHTML=`<div><span>Open area</span><strong>${s.open.toFixed(1)}%</strong></div><div><span>Mirror overlap</span><strong>${union?(both/union*100).toFixed(1):'0.0'}%</strong></div><div><span>Connected regions</span><strong>${s.components}</strong></div>`}
$('#upload').onchange=e=>{const f=e.target.files[0];if(!f)return;const r=new FileReader();r.onload=()=>{const i=new Image();i.onload=()=>{$('#analysisEmpty').hidden=true;$('#analysisCanvas').hidden=false;sourceImage=i;analyze()};i.src=r.result};r.readAsDataURL(f)};$('#threshold').oninput=analyze;$('#imageInvert').onchange=analyze;$('#exportAnalysis').onclick=()=>{if(!sourceImage)return toast('Import an image first');const blob=new Blob([JSON.stringify({source:'local image',threshold:$('#threshold').value,invert:$('#imageInvert').checked,notes:$('#sampleNotes').value,method:'threshold + 8-neighbour components'},null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='lace-image-observation.json';a.click()};
$$('dialog .dialog-close').forEach(b=>b.onclick=()=>b.closest('dialog').close());
setupChoices();sync();renderAtlas();checkConnection();if(location.hash)showPage(location.hash.slice(1));
